'use strict';
const $=s=>document.querySelector(s), esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const uid=()=>crypto.randomUUID(), KEY='cjh-edit-workbench-v1', media=new Map();
const pages=[['overview','◫','项目总览','00'],['materials','▧','素材与脚本','01'],['speech','≋','台词与角色','02'],['matching','⌘','食物画面匹配','03'],['packaging','✦','综艺包装清单','04'],['review','✓','验收与提效','05'],['engines','⚙','工具接入','']];
const descriptions={overview:['把时间留给好内容。','让 AI 做准备，让剪辑师做决定。每一个判断，都能回到素材。'],materials:['好剪辑，从素材开始。','本地预览、人工分组、脚本归档。先确认菜品，再谈匹配。'],speech:['先分清谁在说，再选怎么剪。','导入带时间码的转写，确认人物角色与台词用途。'],matching:['让每一句话，都有对应画面。','按菜名筛选已标注素材，预览候选，再确认入选范围。'],packaging:['判断留给人，重复交给流程。','记录笑点、包装意图与时间位置，导出给剪辑执行工具。'],review:['提效，算上纠错才算数。','记录人工投入、阻塞等待、积分与返工，生成可汇报的结果。'],engines:['把工具接进来，把边界说清楚。','连接本机服务，执行语音分析、多轨粗剪和基础包装。']};
const checks=['达人、编导与闺蜜角色已核对','正式口播与现场指导已区分','食物与菜名、台词对应正确','试吃反应、停顿和互动完整','花字未遮挡，音效未盖住台词','画面、字幕与声音同步，无黑场'];
function fresh(name='我的第一个剪辑项目'){return {id:uid(),name,created:new Date().toISOString(),script:'',assets:[],segments:[],roles:[],matches:[],effects:[],checks:checks.map(()=>false),metrics:{baseline:'',prep:'',review:'',blocked:'',runtime:'',credits:'',creditPrice:'',failures:'',attempts:''},notes:'',timer:{elapsed:0,started:null}};}
let state;try{state=JSON.parse(localStorage.getItem(KEY));}catch{}
if(!state||!Array.isArray(state.projects)||!state.projects.length){const p=fresh();state={version:1,current:p.id,projects:[p]};}
let page='overview',filter='',lastReport='',modalSave=null;
const project=()=>state.projects.find(p=>p.id===state.current)||state.projects[0];
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));$('#save-status').textContent='已保存到此浏览器';}catch{$('#save-status').textContent='保存失败，请导出备份';toast('浏览器存储已满或不可用，请立即导出项目备份');}}
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(toast.t);toast.t=setTimeout(()=>$('#toast').classList.remove('show'),3400);}
function download(name,text,type='text/plain;charset=utf-8'){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),2000);}
function num(x){return Number(x)||0;}function tc(s){const n=Math.max(0,num(s));return `${String(Math.floor(n/60)).padStart(2,'0')}:${(n%60).toFixed(1).padStart(4,'0')}`;}function parseTime(t){if(typeof t==='number')return t;return String(t).replace(',','.').split(':').reduce((a,b)=>a*60+num(b),0);}function bytes(n){return n>1e9?(n/1e9).toFixed(1)+' GB':(n/1e6).toFixed(1)+' MB';}
const tag=(text,cls='neutral')=>`<span class="badge ${cls}">${esc(text)}</span>`;
const empty=(title,sub,action='',label='')=>`<div class="empty"><div class="empty-icon">＋</div><strong>${title}</strong><p>${sub}</p>${action?`<button class="secondary" data-action="${action}">${label}</button>`:''}</div>`;
const field=(name,label,value='',type='text',hint='')=>`<div class="field"><label for="f-${name}">${label}</label><input id="f-${name}" name="${name}" type="${type}" value="${esc(value)}" ${type==='number'?'min="0" step="0.1"':''}>${hint?`<small>${hint}</small>`:''}</div>`;
const selectField=(name,label,value,options)=>`<div class="field"><label for="f-${name}">${label}</label><select id="f-${name}" name="${name}">${options.map(o=>{const [v,t]=Array.isArray(o)?o:[o,o];return `<option value="${esc(v)}" ${v===value?'selected':''}>${esc(t)}</option>`;}).join('')}</select></div>`;
const textField=(name,label,value)=>`<div class="field"><label for="f-${name}">${label}</label><textarea id="f-${name}" name="${name}">${esc(value)}</textarea></div>`;
function openForm(title,html,onSave){$('#modal-title').textContent=title;$('#modal-fields').innerHTML=html;modalSave=onSave;$('#modal').showModal();}
$('#modal-form').onsubmit=e=>{e.preventDefault();const values=Object.fromEntries(new FormData(e.target));try{if(modalSave?.(values)===false)return;save();$('#modal').close();render();}catch(err){toast(err.message);}};
$('#close-modal').onclick=$('#cancel-modal').onclick=()=>$('#modal').close();
$('#close-preview').onclick=()=>$('#preview').close();$('#preview').addEventListener('close',()=>{$('#video').pause();$('#video').removeAttribute('src');$('#video').load();});
function navigate(){page=location.hash.slice(1);if(!pages.some(p=>p[0]===page))page='overview';filter='';render();}window.addEventListener('hashchange',navigate);
function render(){const p=project();$('#nav').innerHTML=pages.map(([id,icon,title,n],i)=>`${i===6?'<div class="nav-divider"></div>':''}<a class="nav-item ${page===id?'active':''}" href="#${id}" ${page===id?'aria-current="page"':''}><span class="nav-icon">${icon}</span><span class="nav-text">${title}</span><span class="nav-index">${n}</span></a>`).join('');$('#crumb').textContent=pages.find(x=>x[0]===page)[2];$('#page-title').textContent=descriptions[page][0];$('#page-desc').textContent=descriptions[page][1];$('#project-select').innerHTML=state.projects.map(x=>`<option value="${esc(x.id)}" ${x.id===p.id?'selected':''}>${esc(x.name)}</option>`).join('');$('#app').innerHTML=({overview,materials,speech,matching,packaging,review,engines,...(window.extraPages||{})}[page])();bindPage();}
function overview(){const p=project(), kept=p.segments.filter(s=>s.decision==='保留').length, matched=p.matches.filter(m=>m.confirmed).length, ready=p.effects.filter(x=>x.status==='已验收').length;const steps=[['materials','素材与脚本','导入本地素材，确认餐厅、菜名和脚本。',`${p.assets.length} 个素材 · ${p.script?'已有脚本':'待导入脚本'}`,p.assets.length&&p.script],['speech','台词与角色确认','明确谁在说话，保留正式口播和有效互动。',`${kept} 条保留 · ${p.segments.filter(s=>s.decision==='待确认').length} 条待确认`,p.segments.length&&!p.segments.some(s=>s.decision==='待确认')],['matching','食物候选匹配','从正确菜品中挑画面，保留人物反应。',`${matched} / ${p.matches.length} 处人工确认`,p.matches.length&&matched===p.matches.length],['packaging','综艺包装执行单','锁定笑点，安排花字、放大、音效和回放。',`${ready} / ${p.effects.length} 项已验收`,p.effects.length&&ready===p.effects.length],['review','验收与提效复盘','把等待与修正计入，留下可追溯结果。',`${p.checks.filter(Boolean).length} / ${checks.length} 项验收`,p.checks.every(Boolean)]];let active=steps.findIndex(s=>!s[4]);const stats=[['素材已登记',p.assets.length,'个','文件留在本机，不上传','▧'],['待确认台词',p.segments.filter(s=>s.decision==='待确认').length,'条','先确认身份，再决定保留','≋'],['已匹配食物',matched,'处','人工确认的画面匹配','⌘'],['包装待执行',p.effects.filter(e=>e.status==='待执行').length,'项','时间码＋意图＋模板','✦']];return `<div class="stats">${stats.map(([l,n,u,d,i])=>`<div class="stat"><div class="stat-top">${l}<span class="stat-icon">${i}</span></div><div class="stat-number">${n}<small>${u}</small></div><p>${d}</p></div>`).join('')}</div><div class="grid"><div><section class="panel"><div class="panel-head"><div><div class="section-kicker">PRODUCTION PIPELINE</div><h2>一条片子的完整路径</h2></div>${tag('5 个制作环节','green')}</div><div class="workflow">${steps.map((s,i)=>`<div class="workflow-item ${i===active?'current':''}"><div class="step-icon">${s[4]?'✓':String(i+1).padStart(2,'0')}</div><div class="step-body"><div class="step-top"><a href="#${s[0]}">${s[1]} ↗</a>${tag(s[4]?'记录已完成':i===active?'从这里开始':'待处理',s[4]?'green':i===active?'orange':'neutral')}</div><p>${s[2]}</p><div class="step-meta">${s[3]}</div></div></div>`).join('')}</div></section><section class="panel"><div class="panel-head"><h2>项目交接</h2><button class="text-button" data-action="prompt">导出剪映指令 ↗</button></div><div class="panel-pad"><p class="subtle">指令会包含当前脚本、已确认角色、食物匹配及包装要求。请在剪辑软件中执行，再回到这里记录实际结果。</p><div class="toolbar-group" style="margin-top:16px"><button class="secondary" data-action="plan-json">导出结构化执行单</button><button class="secondary" data-action="report">生成汇报记录</button></div></div></section></div><aside><div class="right-hero"><span class="pill">EDITORIAL FIRST</span><div class="orb"></div><h2>好笑的那半秒，<br>值得留给人判断。</h2><p>AI 可以帮你找素材、做包装。<br>铺垫、反应和笑点，由你掌握。</p><button class="secondary" data-action="demo">体验示例项目 ↗</button><p style="margin-top:9px;font-size:9px">示例仅演示操作，不代表真实测试结果。</p></div><section class="panel"><div class="panel-head"><h3>本轮重点核对</h3><span class="badge orange">审片提示</span></div><div class="note-list"><div class="note"><i class="note-dot"></i><div>说话人 A 不一定是达人<small>每份录音的身份需单独核对</small></div></div><div class="note"><i class="note-dot"></i><div>同类菜品，不代表同一道菜<small>先确认菜名，再挑局部细节</small></div></div><div class="note"><i class="note-dot"></i><div>分析完成，不等于剪辑正确<small>以实际时间线和成片为准</small></div></div></div></section></aside></div>`;}
function materials(){const p=project(),assets=p.assets.filter(a=>[a.name,a.dish,a.group,a.kind].join(' ').toLowerCase().includes(filter.toLowerCase()));return `<div class="grid"><div><div class="drop" id="drop"><div style="font-size:25px;color:#90a475">▧</div><h3>把本次素材带进工作台</h3><p>拖入视频、音频或图片 · 只读取本机文件，不上传</p><button class="primary" data-action="import-media">选择素材 / 重新关联</button></div><div class="toolbar"><input class="search" id="asset-search" placeholder="搜索文件名、菜名、餐厅…" aria-label="搜索素材" value="${esc(filter)}"><span class="subtle">${assets.length} 个素材 · 标签人工确认</span></div><section class="panel">${assets.length?`<div class="table-wrap"><table><thead><tr><th>素材</th><th>分组 / 菜名</th><th>轨道用途</th><th>操作</th></tr></thead><tbody>${assets.map(a=>`<tr><td><div class="filename" title="${esc(a.name)}"><span class="fileicon">${a.type.startsWith('audio')?'♫':a.type.startsWith('image')?'▨':'▷'}</span>${esc(a.name)}</div><small>${bytes(a.size)} · ${media.has(a.id)?'可预览':'需重新选择文件关联'}</small></td><td>${esc(a.group||'未分组')}<small>${esc(a.dish||'菜名待确认')}</small></td><td>${tag(a.kind)}</td><td class="row-actions"><button class="text-button" data-action="preview" data-id="${esc(a.id)}">预览</button><button class="text-button" data-action="edit-asset" data-id="${esc(a.id)}">标注</button></td></tr>`).join('')}</tbody></table></div>`:empty('还没有素材','先导入，再按人物、食物或环境分类。')}</section></div><div><section class="panel"><div class="panel-head"><h2>剪辑脚本</h2><button class="text-button" data-action="import-script">导入 TXT</button></div><textarea class="script-area" id="script" aria-label="项目脚本" placeholder="粘贴脚本或之前生成的剪映助手文稿。这里只保存文本，不会自动执行剪辑。">${esc(p.script)}</textarea><div class="info-strip"><span id="script-count">${p.script.length} 字</span><span>输入后自动保存</span></div></section><div class="alert">重新打开页面后，素材标签仍在。要播放视频，请再次选择原文件进行关联。视频本体不存入浏览器记录。</div></div></div>`;}
function speech(){const p=project();return `<div class="alert">先将转写里的说话人标签对应到真实角色，再逐句判断用途。不同文件的相同标签不会自动合并为同一个人。导入 SRT 后，角色默认待确认。</div><div class="toolbar"><div class="toolbar-group"><button class="primary" data-action="import-transcript">↙ 导入转写 SRT / JSON</button><button class="secondary" data-action="add-segment">＋ 手动添加台词</button></div><button class="text-button" data-action="transcript-template">下载 JSON 格式示例</button></div><section class="panel"><div class="panel-head"><div><h2>说话人对应表</h2><p>按源文件建立标签与角色的对应关系</p></div><button class="secondary" data-action="add-role">＋ 确认角色</button></div>${p.roles.length?`<div class="table-wrap"><table><thead><tr><th>源文件</th><th>说话人标签</th><th>人工确认角色</th><th>操作</th></tr></thead><tbody>${p.roles.map(r=>`<tr><td>${esc(r.source)}</td><td>${esc(r.speaker)}</td><td>${tag(r.role,'green')}</td><td><button class="text-button" data-action="edit-role" data-id="${esc(r.id)}">编辑</button></td></tr>`).join('')}</tbody></table></div>`:empty('谁在说话？由你确认','模型只给标签，达人、编导和闺蜜需要人工对应。')}</section><section class="panel"><div class="panel-head"><h2>台词审核清单</h2>${tag(`${p.segments.length} 条`)}</div>${p.segments.length?`<div class="table-wrap"><table><thead><tr><th>源素材 / 时间</th><th>角色</th><th>台词</th><th>决定</th><th></th></tr></thead><tbody>${p.segments.map(s=>`<tr><td><div class="filename">${esc(s.source)}</div><small class="timecode">${tc(s.start)} — ${tc(s.end)}</small></td><td>${tag(roleFor(s),roleFor(s)==='待确认'?'orange':'green')}<small>${esc(s.speaker)}</small></td><td style="min-width:230px">${esc(s.text)}</td><td><select class="inline-select" aria-label="台词决定" data-decision="${esc(s.id)}">${['待确认','保留','排除'].map(t=>`<option ${s.decision===t?'selected':''}>${t}</option>`).join('')}</select></td><td><button class="text-button" data-action="edit-segment" data-id="${esc(s.id)}">编辑</button></td></tr>`).join('')}</tbody></table></div>`:empty('导入转写，开始选段','可在执行中心运行本机转写，或导入外部工具结果。')}</section>`;}
function roleFor(s){return project().roles.find(r=>r.source===s.source&&r.speaker===s.speaker)?.role||'待确认';}
function matching(){const p=project();return `<div class="toolbar"><div class="subtle">候选来自你确认过的菜名和餐厅标签，不是 AI 视觉识别结果。</div><button class="primary" data-action="add-match">＋ 新建匹配位置</button></div>${p.matches.length?`<div class="card-grid">${p.matches.map(m=>{const a=p.assets.find(a=>a.id===m.assetId),count=p.assets.filter(a=>a.kind==='食物'&&a.dish===m.dish&&a.group===m.group).length;return `<article class="match-card"><h3>${esc(m.dish)} ${tag(m.confirmed?'人工已确认':'待选画面',m.confirmed?'green':'orange')}</h3><div class="subtle">${esc(m.group)} · 主时间线 ${tc(m.at)}</div><div class="match-quote">${esc(m.quote)}</div><p class="subtle">需要的画面：${esc(m.need||'未填写')}</p><div class="match-selected">${a?`已选：${esc(a.name)}<br>源片段 ${tc(m.start)} — ${tc(m.end)}`:'尚未选定候选素材'}<br><span class="subtle">同组同菜名：${count} 个候选</span></div><div class="toolbar"><button class="secondary" data-action="edit-match" data-id="${esc(m.id)}">选择 / 修改</button>${a?`<button class="text-button" data-action="preview" data-id="${esc(a.id)}" data-start="${m.start}">预览选段 ↗</button>`:''}</div></article>`;}).join('')}</div>`:empty('先提出一个具体的找画面需求','例如：台词说“蘸着烧鹅汁”时，寻找烧鹅蘸汁动作。','add-match','建立第一处匹配')}<div class="alert warm" style="margin-top:20px">给主线标时间前，请先确定粗剪结构。后续主线增删后，需要重新核对匹配位置与包装时间；本工作台不会自动跟随剪辑软件的时间线变化。</div>`;}
function packaging(){const p=project();return `<div class="toolbar"><div class="toolbar-group"><button class="primary" data-action="add-effect">＋ 添加包装标记</button><button class="secondary" data-action="effect-csv">导出包装 CSV</button></div><button class="text-button" data-action="prompt">导出剪映执行指令 ↗</button></div><section class="panel"><div class="panel-head"><div><h2>包装执行单</h2><p>每个动作都有明确位置、意图与验收状态</p></div>${tag('人工确认 · 执行中心落剪')}</div><div class="timeline-strip"><div class="track"><span class="track-label">V2 食物</span><div class="track-line"><span class="clip blank"></span><span class="clip food">菜品细节</span><span class="clip blank"></span><span class="clip food">动作特写</span></div></div><div class="track"><span class="track-label">V1 人物</span><div class="track-line"><span class="clip">铺垫</span><span class="clip">表达</span><span class="clip">反应</span><span class="clip">回应</span></div></div><div class="subtle" style="font-size:9px">轨道分工示意，不是当前项目的真实时间线</div></div>${p.effects.length?`<div class="table-wrap"><table><thead><tr><th>成片位置</th><th>类型 / 模板</th><th>内容与意图</th><th>状态</th><th></th></tr></thead><tbody>${p.effects.map(e=>`<tr><td class="timecode">${tc(e.at)}<small>持续 ${e.duration} 秒</small></td><td>${tag(e.type)}<small>${esc(e.preset||'未指定模板')}</small></td><td style="min-width:210px">${esc(e.text)}<small>${esc(e.intent)}</small></td><td><select class="inline-select" aria-label="包装状态" data-effect-status="${esc(e.id)}">${['待执行','已执行待验收','已验收','需返工'].map(s=>`<option ${s===e.status?'selected':''}>${s}</option>`).join('')}</select></td><td><button class="text-button" data-action="edit-effect" data-id="${esc(e.id)}">编辑</button></td></tr>`).join('')}</tbody></table></div>`:empty('把笑点转成明确的动作','例如：反应放大、吐槽花字、疑惑音效或前文回放。','add-effect','添加第一条包装')}</section><div class="alert">导出的 JSON 是供技术同事对接的执行清单，并非可直接导入剪映的草稿。花字和音效资源需在实际编辑器中确认可用。</div>`;}
function review(){const p=project(),m=p.metrics;return `<div class="grid"><div><section class="panel"><div class="panel-head"><h2>这次到底省了多少时间？</h2>${tag('实测填写','green')}</div><div class="panel-pad"><div class="metrics-grid">${[['baseline','纯人工基准 / 分钟'],['prep','AI流程准备与标注 / 分钟'],['review','审片与修正 / 分钟'],['blocked','无法另做工作的等待 / 分钟'],['runtime','机器总运行 / 分钟'],['credits','实际扣除积分'],['creditPrice','每积分实际成本 / 元'],['attempts','总执行次数'],['failures','失败次数']].map(([k,l])=>`<div class="field"><label for="metric-${k}">${l}</label><input type="number" id="metric-${k}" data-metric="${k}" min="0" step="${k==='creditPrice'?'.001':'.1'}" value="${esc(m[k])}" placeholder="未记录"></div>`).join('')}</div><div class="subtle">准备、审片、阻塞等待分开计时，不重复相加。机器总运行时间单独展示，不再叠加到人工占用中。</div><div class="result-box" id="result-box">${metricsResult()}</div><div class="timer"><div><small>审片计时器</small><strong id="timer-text" style="display:block">${timerText()}</strong></div><button class="secondary" data-action="timer">${p.timer.started?'暂停':'开始 / 继续'}</button><button class="text-button" data-action="timer-record">填入审片分钟数</button></div></div></section><section class="panel"><div class="panel-head"><h2>测试发现与返工记录</h2></div><div class="panel-pad"><textarea class="script-area" id="review-notes" style="min-height:140px;border:1px solid var(--line);border-radius:8px" aria-label="测试记录" placeholder="记录具体错误、任务失败、重试以及人工修改情况…">${esc(p.notes)}</textarea></div></section></div><div><section class="panel"><div class="panel-head"><h2>交付前检查</h2></div><div class="panel-pad"><div class="checklist">${checks.map((c,i)=>`<label><input type="checkbox" data-check="${i}" ${p.checks[i]?'checked':''}>${c}</label>`).join('')}</div></div></section><div class="right-hero"><span class="pill">REVIEW → REPORT</span><h2>让判断有证据。</h2><p>统计来自你的记录。未填写的数据会标记为“未记录”，不推算准确率或节省比例。</p><button class="primary full" data-action="report">生成汇报记录 ↗</button></div></div></div>`;}
function metricsResult(){const m=project().metrics,complete=['baseline','prep','review','blocked'].every(k=>m[k]!==''),cost=m.credits!==''&&m.creditPrice!==''?(num(m.credits)*num(m.creditPrice)).toFixed(2):null;if(!complete)return `<strong style="font-size:17px">等待实测数据</strong><p>填完人工基准、准备、审片与阻塞等待，才计算净节省。积分费用：${cost===null?'待记录单价与扣除量':cost+' 元'}。</p>`;const occupancy=num(m.prep)+num(m.review)+num(m.blocked),delta=num(m.baseline)-occupancy;return `<strong>${delta>=0?'节省':'增加'} ${Math.abs(delta).toFixed(1)} 分钟</strong><p>流程占用 ${occupancy.toFixed(1)} 分钟 / 人工基准 ${num(m.baseline).toFixed(1)} 分钟${num(m.baseline)>0?' · '+(delta/num(m.baseline)*100).toFixed(1)+'% 净节省':''}。积分费用：${cost===null?'待记录':cost+' 元'}。</p>`;}
function timerText(){const t=project().timer,seconds=(num(t.elapsed)+(t.started?Date.now()-t.started:0))/1000;return `${String(Math.floor(seconds/60)).padStart(2,'0')}:${String(Math.floor(seconds%60)).padStart(2,'0')}`;}
setInterval(()=>{if($('#timer-text'))$('#timer-text').textContent=timerText();},1000);
function engines(){const cards=[['声音识别与角色分段','FunClip / pyannote.audio','先在外部工具转写和分段，再导入 SRT 或 JSON。工作台保存原文件、时间范围、说话人标签与人工确认角色。','https://github.com/modelscope/FunClip','查看 FunClip'],['画面理解与候选检索','Qwen3-VL','当前由你标注餐厅和菜品，工作台据此筛候选。自动画面分析尚未接入；接入后仍保留人工确认环节。','https://github.com/QwenLM/Qwen3-VL','查看 Qwen3-VL'],['达芬奇执行','现有桥接 / Resolve MCP','可导出结构化执行单交给已有桥接程序。需要适配轨道、帧率、素材路径和模板后才能自动执行。','https://github.com/samuelgursky/davinci-resolve-mcp','查看连接方案'],['剪映草稿生成','pyJianYingDraft / VectCutAPI','当前可导出可粘贴指令。生成可编辑草稿需要本地运行服务，并验证剪映版本与模板兼容性。','https://github.com/GuanYixuan/pyJianYingDraft','查看草稿项目']];return `<div class="alert warm">当前版本是可使用的流程与审核工作台，没有运行 AI 推理，也没有控制剪映或达芬奇。它能整理输入、预览素材、记录决定并输出交接文件。</div><div class="card-grid">${cards.map(c=>`<article class="engine-card"><h3>${c[0]} ${tag('未连接')}</h3><div class="section-kicker" style="margin-top:8px">${c[1]}</div><p>${c[2]}</p><a href="${c[3]}" target="_blank" rel="noopener">${c[4]} ↗</a></article>`).join('')}</div><section class="panel" style="margin-top:22px"><div class="panel-head"><h2>可以立即使用的交接方式</h2></div><div class="panel-pad"><div class="toolbar-group"><button class="secondary" data-action="prompt">剪映助手指令 TXT</button><button class="secondary" data-action="plan-json">结构化执行单 JSON</button><button class="secondary" data-action="effect-csv">包装清单 CSV</button><button class="secondary" data-action="transcript-template">转写导入示例 JSON</button></div></div></section>`;}
function bindPage(){if($('#script'))$('#script').oninput=e=>{project().script=e.target.value;$('#script-count').textContent=e.target.value.length+' 字';save();};if($('#review-notes'))$('#review-notes').oninput=e=>{project().notes=e.target.value;save();};if($('#asset-search'))$('#asset-search').oninput=e=>{const pos=e.target.selectionStart;filter=e.target.value;render();$('#asset-search').focus();$('#asset-search').setSelectionRange(pos,pos);};const drop=$('#drop');if(drop){drop.ondragover=e=>{e.preventDefault();drop.classList.add('dragover');};drop.ondragleave=()=>drop.classList.remove('dragover');drop.ondrop=e=>{e.preventDefault();importMedia(e.dataTransfer.files);};}}
document.addEventListener('input',e=>{if(e.target.dataset.metric){project().metrics[e.target.dataset.metric]=e.target.value;save();$('#result-box').innerHTML=metricsResult();}});
document.addEventListener('change',e=>{const p=project(),t=e.target;if(t.dataset.decision){p.segments.find(s=>s.id===t.dataset.decision).decision=t.value;save();}if(t.dataset.effectStatus){p.effects.find(s=>s.id===t.dataset.effectStatus).status=t.value;save();}if(t.dataset.metric){p.metrics[t.dataset.metric]=t.value;save();$('#result-box').innerHTML=metricsResult();}if(t.dataset.check!==undefined){p.checks[Number(t.dataset.check)]=t.checked;save();}});
function importMedia(files){const p=project();let added=0;for(const file of files){if(!/^(video|audio|image)\//.test(file.type)){toast('已跳过非媒体文件');continue;}let a=p.assets.find(x=>x.name===file.name&&x.size===file.size&&x.modified===file.lastModified);if(!a){a={id:uid(),name:file.name,type:file.type,size:file.size,modified:file.lastModified,kind:'待分类',group:'',dish:''};p.assets.push(a);added++;}if(media.has(a.id))URL.revokeObjectURL(media.get(a.id).url);media.set(a.id,{file,url:URL.createObjectURL(file)});}save();render();toast(`新增 ${added} 个素材，其余同名同大小文件已重新关联`);}
$('#media-input').onchange=e=>{importMedia(e.target.files);e.target.value='';};
$('#script-input').onchange=async e=>{const file=e.target.files[0];if(file){project().script=await file.text();save();render();toast('脚本文本已导入');}e.target.value='';};
function editAsset(id){const a=project().assets.find(x=>x.id===id);openForm('标注素材',`<p class="subtle" style="margin-bottom:15px">${esc(a.name)}</p>${selectField('kind','素材用途',a.kind,['待分类','人物','食物','环境','声音'])}${field('group','餐厅 / 场景分组',a.group)}${field('dish','人工确认菜名（食物素材填写）',a.dish)}`,v=>Object.assign(a,v));}
function editRole(id){const p=project(),r=p.roles.find(x=>x.id===id);openForm('确认说话人角色',field('source','源文件名',r?.source||'', 'text','须与台词清单中的源文件名一致。')+field('speaker','原始说话人标签',r?.speaker||'SPEAKER_00')+selectField('role','人工确认角色',r?.role||'达人',['达人','编导','闺蜜 / 嘉宾','店员','其他']),v=>{if(!v.source.trim()||!v.speaker.trim())throw Error('请填写源文件和说话人标签');const duplicate=p.roles.find(x=>x.id!==id&&x.source===v.source&&x.speaker===v.speaker);if(duplicate)Object.assign(duplicate,v);else if(r)Object.assign(r,v);else p.roles.push({id:uid(),...v});});}
function editSegment(id){const p=project(),s=p.segments.find(x=>x.id===id);openForm('编辑台词片段',field('source','源文件名',s?.source||'')+field('speaker','说话人标签',s?.speaker||'待确认')+`<div class="fields-row">${field('start','原素材起点 / 秒',s?.start??0,'number')}${field('end','原素材终点 / 秒',s?.end??3,'number')}</div>`+textField('text','原声台词',s?.text||'')+selectField('decision','剪辑决定',s?.decision||'待确认',['待确认','保留','排除']),v=>{if(!v.source.trim()||!v.text.trim())throw Error('请填写文件名与台词');if(num(v.end)<=num(v.start))throw Error('终点必须晚于起点');v.start=num(v.start);v.end=num(v.end);if(s)Object.assign(s,v);else p.segments.push({id:uid(),...v});});}
function editMatch(id){const p=project(),m=p.matches.find(x=>x.id===id);const opts=[['','待选择'],...p.assets.filter(a=>a.kind==='食物').map(a=>[a.id,`${a.group||'未分组'} / ${a.dish||'未标菜名'} · ${a.name}`])];openForm('建立画面与台词的对应关系',`<div class="fields-row">${field('group','餐厅分组',m?.group||'')}${field('dish','菜名',m?.dish||'')}</div>`+field('quote','对应台词',m?.quote||'')+field('need','需要的画面 / 动作',m?.need||'')+field('at','主时间线位置 / 秒',m?.at??0,'number')+selectField('assetId','食物候选素材',m?.assetId||'',opts)+`<div class="fields-row">${field('start','源素材起点 / 秒',m?.start??0,'number')}${field('end','源素材终点 / 秒',m?.end??3,'number')}</div>`+selectField('confirmed','人工确认',m?.confirmed?'yes':'no',[['no','待确认'],['yes','已预览，确认匹配']]),v=>{if(!v.dish.trim()||!v.group.trim()||!v.quote.trim())throw Error('请填写餐厅、菜名与对应台词');if(num(v.end)<=num(v.start))throw Error('源素材终点必须晚于起点');const a=p.assets.find(a=>a.id===v.assetId);if(v.confirmed==='yes'&&(!a||a.dish!==v.dish||a.group!==v.group))throw Error('请先确认候选素材的菜名和餐厅标签与当前需求一致');v.confirmed=v.confirmed==='yes';for(const k of ['at','start','end'])v[k]=num(v[k]);if(m)Object.assign(m,v);else p.matches.push({id:uid(),...v});});}
function editEffect(id){const p=project(),x=p.effects.find(e=>e.id===id);openForm('综艺包装标记',selectField('type','包装类型',x?.type||'花字',['花字','人物放大','音效','回放','音乐避让','其他'])+`<div class="fields-row">${field('at','主时间线位置 / 秒',x?.at??0,'number')}${field('duration','持续时长 / 秒',x?.duration??1.5,'number')}</div>`+field('preset','模板名 / 音效文件名',x?.preset||'')+field('text','花字内容 / 执行动作',x?.text||'')+textField('intent','笑点意图 / 台词锚点 / 构图要求',x?.intent||'')+selectField('status','执行状态',x?.status||'待执行',['待执行','已执行待验收','已验收','需返工']),v=>{if(!v.text.trim())throw Error('请填写包装内容或动作');if(num(v.duration)<=0)throw Error('持续时长需要大于0');v.at=num(v.at);v.duration=num(v.duration);if(x)Object.assign(x,v);else p.effects.push({id:uid(),...v});});}
async function preview(id,start){const a=project().assets.find(a=>a.id===id),entry=media.get(id);if(!entry){toast('请在素材页重新选择该文件，恢复预览关联');return;}if(a.type.startsWith('image')){openForm('图片素材',`<img src="${entry.url}" alt="${esc(a.name)}" style="width:100%;max-height:60vh;object-fit:contain">`,()=>{});return;}$('#preview-title').textContent=a.name;$('#preview-note').textContent='播放源素材，核对动作、菜品与起止点；不自动判断准确性。';$('#video').src=entry.url;$('#video').onloadedmetadata=()=>{$('#video').currentTime=Math.min(num(start),$('#video').duration||0);};$('#preview').showModal();}
function plan(){const p=project();return {schema:'cjh-edit-plan-v1',units:'seconds',project:p.name,generatedAt:new Date().toISOString(),engineConnected:false,script:p.script,roles:p.roles,selectedSpeech:p.segments.filter(s=>s.decision==='保留').map(s=>({...s,role:roleFor(s)})),pendingSpeech:p.segments.filter(s=>s.decision==='待确认'),foodPlacements:p.matches.filter(m=>m.confirmed).map(m=>({...m,file:p.assets.find(a=>a.id===m.assetId)?.name,targetTrack:'V2'})),pendingMatches:p.matches.filter(m=>!m.confirmed),packaging:p.effects,notes:'素材仅提供文件名，执行端须解析本机路径并按项目帧率换算。此 JSON 不是剪映草稿，也不直接调用剪辑软件。'};}
function promptText(){const d=plan();return `请协助剪辑项目《${d.project}》。\n人物画面在主时间线V1，食物补充画面在第二视频轨道V2。保留主线对白连续，食物原声不覆盖人物口播。先核对当前时间线位置再执行，未确认项目不要自行猜测。\n\n【脚本】\n${d.script||'未提供，请先补齐脚本。'}\n\n【已人工确认的说话人】\n${d.roles.map(r=>`${r.source}：${r.speaker} → ${r.role}`).join('\n')||'尚未确认，不能根据说话人编号猜角色。'}\n\n【保留的原声片段（原素材秒数）】\n${d.selectedSpeech.map(s=>`${s.source} ${s.start}—${s.end}秒 / ${s.role}：${s.text}`).join('\n')||'暂无已确认片段，请先核对台词。'}\n尚有${d.pendingSpeech.length}条台词待确认。不要将编导指导、脚本动作提示作为达人口播。\n\n【人工确认的第二轨画面】\n${d.foodPlacements.map(m=>`主线${m.at}秒，台词“${m.quote}”：使用${m.group}的${m.dish}，文件${m.file}，源范围${m.start}—${m.end}秒；目的：${m.need}。`).join('\n')||'暂无已确认匹配，不要用相似菜品代替。'}\n尚有${d.pendingMatches.length}处匹配待确认。保留试吃第一口、惊讶和回应，不用食物特写全程遮挡人物。\n\n【包装执行单】\n${d.packaging.map(e=>`${e.id} / ${e.at}秒 / 持续${e.duration}秒 / ${e.type} / ${e.preset||'模板未指定'} / ${e.text} / ${e.intent} / 当前状态：${e.status}`).join('\n')||'暂无包装要求。'}\n已执行项目先检查，避免重复叠加。模板、音效或接口不支持时报告缺项，不声称已经完成。\n\n如主线结构已变化，请重新定位台词，再核对食物和包装的位置。完成后列出实际执行、未执行及需人工确认的事项。`;}
function reportText(){const p=project(),m=p.metrics,known=k=>m[k]===''?'未记录':m[k];const complete=['baseline','prep','review','blocked'].every(k=>m[k]!==''),occupancy=num(m.prep)+num(m.review)+num(m.blocked);return `AI剪辑测试记录｜${p.name}\n日期：${new Date().toLocaleDateString('zh-CN',{timeZone:'Asia/Shanghai'})}\n\n一、项目记录\n素材：${p.assets.length}个；台词：${p.segments.length}条，其中保留${p.segments.filter(s=>s.decision==='保留').length}条、待确认${p.segments.filter(s=>s.decision==='待确认').length}条。\n食物匹配：人工确认${p.matches.filter(x=>x.confirmed).length}/${p.matches.length}处。\n包装：已验收${p.effects.filter(x=>x.status==='已验收').length}/${p.effects.length}项。\n上述为工作台登记情况，不代表模型准确率。\n\n二、实测投入\n纯人工基准：${known('baseline')}分钟\n准备及标注：${known('prep')}分钟\n审片与修正：${known('review')}分钟\n阻塞等待：${known('blocked')}分钟\n机器总运行：${known('runtime')}分钟（单独展示，不重复计入人工占用）\n${complete?`流程占用合计：${occupancy.toFixed(1)}分钟；相对人工基准净节省：${(num(m.baseline)-occupancy).toFixed(1)}分钟。`:'数据未齐，暂不能判断净提效。'}\n实际扣除积分：${known('credits')}；每积分成本：${known('creditPrice')}元。\n${m.credits!==''&&m.creditPrice!==''?'积分费用：'+(num(m.credits)*num(m.creditPrice)).toFixed(2)+'元。':'积分费用未完整记录。'}\n执行次数：${known('attempts')}；失败次数：${known('failures')}。\n\n三、测试发现\n${p.notes||'尚未填写具体测试发现。'}\n\n四、验收\n${checks.map((c,i)=>`${p.checks[i]?'已确认':'待确认'}：${c}`).join('\n')}\n\n说明：本工作台用于整理素材与人工决定，可通过执行中心连接本机分析与达芬奇。此汇报中的时间、费用仍为人工登记，执行回执以队列为准。`;}
function showReport(){lastReport=reportText();openForm('可复制的测试汇报',`<div class="report" id="report-text">${esc(lastReport)}</div><div class="toolbar-group" style="margin-top:15px"><button type="button" class="secondary" data-action="copy-report">复制全文</button><button type="button" class="secondary" data-action="download-report">下载 TXT</button></div>`,()=>{});}
function demo(){const p=fresh('示例 · 探店综艺剪辑（非实测）');p.script='达人：刚才谁说不饿的？\n闺蜜：我只吃一口。\n达人：先蘸一点烧鹅汁，外脆里嫩。\n闺蜜：这是免税，不是免费啊！';p.assets=[{id:uid(),name:'示例_达人口播.mp4',size:24000000,type:'video/mp4',modified:0,kind:'人物',group:'餐厅A',dish:''},{id:uid(),name:'示例_烧鹅蘸汁.mp4',size:12000000,type:'video/mp4',modified:0,kind:'食物',group:'餐厅A',dish:'烧鹅'}];p.roles=[{id:uid(),source:'示例_达人口播.mp4',speaker:'SPEAKER_00',role:'达人'}];p.segments=[{id:uid(),source:'示例_达人口播.mp4',speaker:'SPEAKER_00',start:2,end:5,text:'刚才谁说不饿的？',decision:'保留'},{id:uid(),source:'示例_达人口播.mp4',speaker:'SPEAKER_01',start:6,end:8,text:'再来一遍，先看镜头。',decision:'待确认'}];p.matches=[{id:uid(),dish:'烧鹅',group:'餐厅A',quote:'先蘸一点烧鹅汁',need:'完整蘸汁动作',at:18,start:1,end:3,assetId:p.assets[1].id,confirmed:false}];p.effects=[{id:uid(),type:'花字',at:32,duration:1.5,preset:'吐槽款',text:'免税 ≠ 免费',intent:'闺蜜说完再出现，保留达人反应。',status:'待执行'}];state.projects.push(p);state.current=p.id;save();render();toast('已新建独立示例，不包含真实视频或测试数据');}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action,id=b.dataset.id,p=project();if(a==='import-media')$('#media-input').click();else if(a==='import-script')$('#script-input').click();else if(a==='import-transcript')$('#transcript-input').click();else if(a==='edit-asset')editAsset(id);else if(a==='preview')preview(id,b.dataset.start);else if(a==='add-role'||a==='edit-role')editRole(id);else if(a==='add-segment'||a==='edit-segment')editSegment(id);else if(a==='add-match'||a==='edit-match')editMatch(id);else if(a==='add-effect'||a==='edit-effect')editEffect(id);else if(a==='demo')demo();else if(a==='prompt'){download(p.name+'_剪映助手指令.txt',promptText());toast('已导出指令，请在剪映中执行并验收');}else if(a==='plan-json')download(p.name+'_执行清单.json',JSON.stringify(plan(),null,2),'application/json');else if(a==='effect-csv'){const rows=[['编号','成片秒数','时长秒','类型','模板','内容','意图','状态'],...p.effects.map(x=>[x.id,x.at,x.duration,x.type,x.preset,x.text,x.intent,x.status])];const cell=x=>'"'+String(x??'').replace(/^[=+@-]/,"'$&").replaceAll('"','""')+'"';download(p.name+'_包装清单.csv','\ufeff'+rows.map(r=>r.map(cell).join(',')).join('\r\n'),'text/csv;charset=utf-8');}else if(a==='transcript-template')download('转写导入格式示例.json',JSON.stringify({segments:[{source:'请替换为真实原素材.mp4',speaker:'SPEAKER_00',start:1.2,end:4.8,text:'这里填写真实转写内容'}]},null,2),'application/json');else if(a==='report')showReport();else if(a==='download-report')download(p.name+'_测试汇报.txt',lastReport);else if(a==='copy-report'){try{await navigator.clipboard.writeText(lastReport);toast('汇报已复制');}catch{toast('剪贴板不可用，请下载TXT');}}else if(a==='timer'){if(p.timer.started){p.timer.elapsed+=Date.now()-p.timer.started;p.timer.started=null;}else p.timer.started=Date.now();save();render();}else if(a==='timer-record'){p.metrics.review=((p.timer.elapsed+(p.timer.started?Date.now()-p.timer.started:0))/60000).toFixed(1);save();render();toast('已填入审片时间，请勿重复计入其他项');}});
$('#project-select').onchange=e=>{state.current=e.target.value;save();render();};
$('#new-project').onclick=()=>openForm('新建剪辑项目',field('name','项目名称','','text','例如：达人 · 示例广场示例广场'),v=>{if(!v.name.trim())throw Error('请填写项目名称');const p=fresh(v.name.trim());state.projects.push(p);state.current=p.id;});
$('#rename').onclick=()=>openForm('重命名项目',field('name','项目名称',project().name),v=>{if(!v.name.trim())throw Error('名称不能为空');project().name=v.name.trim();});
$('#backup').onclick=()=>{download(project().name+'_工作台备份.json',JSON.stringify({version:1,project:project()},null,2),'application/json');toast('备份包含记录，不包含视频文件');};
$('#restore').onclick=()=>$('#restore-input').click();
$('#restore-input').onchange=async e=>{try{const raw=JSON.parse(await e.target.files[0].text()),p=raw.project;if(raw.version!==1||!p||typeof p.name!=='string'||!['assets','segments','roles','matches','effects','checks'].every(k=>Array.isArray(p[k]))||typeof p.script!=='string')throw Error('不是有效的工作台V1项目备份');const clean=fresh(p.name+'（恢复）');for(const k of ['script','assets','segments','roles','matches','effects','checks','metrics','notes'])if(p[k]!==undefined)clean[k]=p[k];clean.timer={elapsed:num(p.timer?.elapsed),started:null};state.projects.push(clean);state.current=clean.id;save();render();toast('已恢复为新项目，原项目未覆盖');}catch(err){toast('恢复失败：'+err.message);}e.target.value='';};
$('#transcript-input').onchange=async e=>{try{const file=e.target.files[0],text=await file.text();let items;if(file.name.toLowerCase().endsWith('.json')){const data=JSON.parse(text);items=Array.isArray(data)?data:data.segments;if(!Array.isArray(items))throw Error('需要segments数组');}else{items=text.replace(/^\uFEFF/,'').trim().split(/\r?\n\s*\r?\n/).map(block=>{const lines=block.split(/\r?\n/),i=lines.findIndex(l=>l.includes('-->'));if(i<0)return null;const pair=lines[i].split('-->');return {source:file.name.replace(/\.srt$/i,'.mp4'),speaker:'待确认',start:parseTime(pair[0].trim()),end:parseTime(pair[1].trim().split(/\s/)[0]),text:lines.slice(i+1).join(' ')};}).filter(Boolean);}if(!items.length)throw Error('没有可用台词');const parsed=items.map(s=>{if(!Number.isFinite(Number(s.start))||!Number.isFinite(Number(s.end))||Number(s.end)<=Number(s.start)||!s.text||!s.source)throw Error('片段需要source、start、end和text，且时间范围有效');return {id:uid(),source:String(s.source),speaker:String(s.speaker||'待确认'),start:Number(s.start),end:Number(s.end),text:String(s.text),decision:'待确认'};});project().segments.push(...parsed);save();render();toast(`导入 ${parsed.length} 条台词，待人工确认。SRT文件名仅作原视频名推定。`);}catch(err){toast('导入失败：'+err.message);}e.target.value='';};
$('#help').onclick=()=>openForm('如何开始一条片子的制作',`<ol class="help-list"><li>新建项目，在素材页选择本地视频并标注。</li><li>粘贴脚本，导入外部工具输出的转写。</li><li>确认说话人角色和要保留的台词。</li><li>在食物匹配页选素材、填范围并预览确认。</li><li>添加综艺包装，导出指令或执行清单。</li><li>在剪辑软件执行，回来记录结果、耗时和返工。</li></ol><div class="alert">这不是剪辑软件或自动识别引擎。浏览器保存的是记录，视频只临时预览；清除浏览器数据前请导出备份。</div>`,()=>{});
save();navigate();
